PRAGMA journal_mode=WAL;
CREATE TABLE IF NOT EXISTS merchants(id TEXT PRIMARY KEY,name TEXT NOT NULL,key_hash TEXT UNIQUE NOT NULL,secret TEXT NOT NULL,webhook TEXT NOT NULL,return_url TEXT NOT NULL,active INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS payments(id TEXT PRIMARY KEY,merchant TEXT NOT NULL REFERENCES merchants(id),order_id TEXT NOT NULL,amount INTEGER NOT NULL,currency TEXT NOT NULL DEFAULT 'KES',status TEXT NOT NULL DEFAULT 'PENDING',token TEXT UNIQUE NOT NULL,checkout_id TEXT UNIQUE,receipt TEXT UNIQUE,created INTEGER NOT NULL,expires INTEGER NOT NULL,phone TEXT,UNIQUE(merchant,order_id));
CREATE TABLE IF NOT EXISTS events(id TEXT PRIMARY KEY,payment TEXT NOT NULL UNIQUE REFERENCES payments(id),body TEXT NOT NULL,attempts INTEGER NOT NULL DEFAULT 0,next_at INTEGER NOT NULL DEFAULT 0,delivered INTEGER NOT NULL DEFAULT 0,last_error TEXT);
CREATE TABLE IF NOT EXISTS callback_log(digest TEXT PRIMARY KEY,received INTEGER NOT NULL,outcome TEXT NOT NULL);
